import app from 'flarum/admin/app';

const m = window.m;

function copyToClipboard(text) {
    if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text);
    else { let ta = document.createElement('textarea'); ta.value = text; ta.style.position = 'fixed'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); }
}

class SeoAdminPage {
    oninit(vnode) {
        this.setting    = vnode.attrs.setting;
        this.activeTab  = 'dashboard';
        this.loading    = false;
        this.data = {
            dashboard : null,
            indexing  : { items: [], page: 1, total_pages: 1 },
            images    : { all: [], page: 1, perPage: 20, count: 0 },
            cache     : JSON.parse(localStorage.getItem('st_seo_cache_v3')) || {}
        };
        this.loadDashboard();
    }

    saveCache(url, data) {
        this.data.cache[url] = data;
        localStorage.setItem('st_seo_cache_v3', JSON.stringify(this.data.cache));
    }

    loadDashboard() {
        this.loading = true;
        m.request({ method: 'GET', url: app.forum.attribute('apiUrl') + '/seo/stats', headers: { 'X-CSRF-Token': app.session.csrfToken } })
         .then(res  => { this.data.dashboard = res; this.loading = false; m.redraw(); })
         .catch(()  => { this.loading = false; m.redraw(); });
    }

    loadIndexing() {
        this.loading = true;
        m.request({ method: 'GET', url: app.forum.attribute('apiUrl') + '/seo/content', params: { page: this.data.indexing.page }, headers: { 'X-CSRF-Token': app.session.csrfToken } })
         .then(res  => { this.data.indexing.items = res.items || []; this.data.indexing.total_pages = res.total_pages || 1; this.loading = false; m.redraw(); })
         .catch(()  => { this.loading = false; m.redraw(); });
    }

    loadImages() {
        this.loading = true;
        this.data.images.page = 1;
        m.request({ method: 'GET', url: app.forum.attribute('apiUrl') + '/seo/images', headers: { 'X-CSRF-Token': app.session.csrfToken } })
         .then(res => {
             this.data.images.all   = (res.status === 'success') ? (res.images || []) : [];
             this.data.images.count = (res.status === 'success') ? (res.count  || 0)  : 0;
             this.loading = false;
             m.redraw();
         })
         .catch(() => { this.data.images.all = []; this.data.images.count = 0; this.loading = false; m.redraw(); });
    }

    // ---------- VIEW ----------
    view() {
        const d   = this.data.dashboard;
        const gsc = (d && d.gsc)  ? d.gsc  : { clicks: 0, impressions: 0, top_queries: [] };
        const ga  = (d && d.ga4)  ? d.ga4  : { active_users: 0, screen_views: 0, top_pages: [] };

        // Görsel SEO sayfalama
        const imgAll      = this.data.images.all;
        const imgPg       = this.data.images.page;
        const imgPerPg    = this.data.images.perPage;
        const imgTotalPg  = Math.max(1, Math.ceil(imgAll.length / imgPerPg));
        const imgSlice    = imgAll.slice((imgPg - 1) * imgPerPg, imgPg * imgPerPg);

        return m('div.SeoPack-Admin', [

            // ── TAB MENÜ ──────────────────────────────────────────────
            m('div.SeoTabs', [
                m('button.SeoTab', { className: this.activeTab === 'dashboard' ? 'active' : '', onclick: e => { e.preventDefault(); this.activeTab = 'dashboard'; this.loadDashboard(); } }, [m('i.fas.fa-chart-pie'), ' Dashboard']),
                m('button.SeoTab', { className: this.activeTab === 'indexing'  ? 'active' : '', onclick: e => { e.preventDefault(); this.activeTab = 'indexing';  this.loadIndexing();  } }, [m('i.fas.fa-list-ul'), ' İndeks Yönetimi']),
                m('button.SeoTab', { className: this.activeTab === 'images'    ? 'active' : '', onclick: e => { e.preventDefault(); this.activeTab = 'images';    this.loadImages();    } }, [m('i.fas.fa-images'), ' Görsel SEO']),
                m('button.SeoTab', { className: this.activeTab === 'settings'  ? 'active' : '', onclick: e => { e.preventDefault(); this.activeTab = 'settings';  m.redraw();           } }, [m('i.fas.fa-cogs'), ' Ayarlar'])
            ]),

            m('div.SeoContent', [

                // ── 1. DASHBOARD ──────────────────────────────────────
                this.activeTab !== 'dashboard' ? null : m('div', [
                    m('div.StatGrid', { style: 'display:flex; gap:10px; margin-bottom:20px; flex-wrap:wrap;' },
                        [['Web Tık', gsc.clicks, '#3498db', 'mouse-pointer'], ['Resim Tık', (d && d.img_gsc ? d.img_gsc.clicks : 0), '#e74c3c', 'images'], ['Gösterim', gsc.impressions, '#9b59b6', 'eye'], ['Aktif', ga.active_users, '#27ae60', 'users']].map(c =>
                            m('div', { style: 'flex:1; background:#fff; padding:15px; border-radius:8px; border:1px solid #eee; text-align:center;' }, [
                                m('div', { style: 'color:#888; font-size:11px; text-transform:uppercase;' }, c[0]),
                                m('div', { style: 'font-size:26px; font-weight:bold; color:#2d3436; margin:6px 0;' }, c[1]),
                                m('i', { className: 'fas fa-' + c[3], style: 'color:' + c[2] })
                            ])
                        )
                    ),
                    m('div', { style: 'display:flex; gap:20px; flex-wrap:wrap;' }, [
                        m('div.SeoCard', { style: 'flex:1; min-width:240px;' }, [
                            m('h4', { style: 'margin-top:0; color:#2980b9;' }, '🔍 En Çok Arananlar'),
                            m('table', { style: 'width:100%; border-collapse:collapse;' },
                                gsc.top_queries.map(q => m('tr', [m('td', { style: 'padding:6px 0; border-bottom:1px solid #f0f0f0;' }, q.keyword), m('td', { style: 'text-align:right; font-weight:bold;' }, q.clicks)]))
                            )
                        ]),
                        m('div.SeoCard', { style: 'flex:1; min-width:240px;' }, [
                            m('h4', { style: 'margin-top:0; color:#27ae60;' }, '📈 Popüler Sayfalar'),
                            m('table', { style: 'width:100%; border-collapse:collapse;' },
                                ga.top_pages.map(p => m('tr', [m('td', { style: 'padding:6px 0; border-bottom:1px solid #f0f0f0; color:#555;' }, p.path), m('td', { style: 'text-align:right; font-weight:bold;' }, p.views)]))
                            )
                        ])
                    ])
                ]),

                // ── 2. İNDEKS YÖNETİMİ ───────────────────────────────
                this.activeTab !== 'indexing' ? null : m('div.SeoCard', [
                    m('h3', { style: 'margin-top:0;' }, 'Detaylı İçerik İndeks Takibi'),
                    this.loading ? m('p', 'Yükleniyor...') : m('table', { style: 'width:100%; border-collapse:collapse;' }, [
                        m('thead', { style: 'background:#f8f9fa; border-bottom:2px solid #e9ecef;' }, m('tr', [
                            m('th', { style: 'padding:12px 15px; text-align:left; font-size:12px; color:#555; text-transform:uppercase;' }, 'Konu'),
                            m('th', { style: 'padding:12px 15px; text-align:left; font-size:12px; color:#555; text-transform:uppercase;' }, 'Detay'),
                            m('th', { style: 'padding:12px 15px; text-align:left; font-size:12px; color:#555; text-transform:uppercase;' }, 'Durum'),
                            m('th', { style: 'padding:12px 15px; text-align:left; font-size:12px; color:#555; text-transform:uppercase;' }, 'Canlı Kontrol')
                        ])),
                        m('tbody', this.data.indexing.items.map(item => {
                            const cached = this.data.cache[item.url] || {};
                            let label = '🔴 Bekliyor', color = '#e74c3c';
                            if (item.seo_last_sent_at) {
                                if (item.last_posted_at && item.last_posted_at > item.seo_last_sent_at) { label = '🟡 Yeni Yorum Var'; color = '#f39c12'; }
                                else { label = '🟢 Senkronize'; color = '#27ae60'; }
                            }
                            return m('tr', { style: 'border-bottom:1px solid #f1f3f5;' }, [
                                m('td', { style: 'padding:14px 15px; vertical-align:middle;' }, [m('b', { style: 'color:#2c3e50;' }, item.title), m('br'), m('small', { style: 'color:#868e96;' }, item.url)]),
                                m('td', { style: 'padding:14px 15px; vertical-align:middle; font-size:12px; color:#555;' }, [
                                    m('div', { style: 'margin-bottom:2px;' }, '💬 ' + item.comment_count + ' Yorum'),
                                    m('div', { style: 'margin-bottom:2px;' }, '⏱️ ' + (item.last_posted_at || '-')),
                                    m('div', { style: 'color:#0984e3;' }, '🌐 ' + (item.seo_last_sent_at || '-'))
                                ]),
                                m('td', { style: 'padding:14px 15px; vertical-align:middle;' },
                                    m('span', { style: 'background:' + color + '15; color:' + color + '; padding:5px 12px; border-radius:20px; font-size:11px; font-weight:bold; border:1px solid ' + color + '40;' }, label)
                                ),
                                m('td', { style: 'padding:14px 15px; vertical-align:middle;' }, [
                                    m('button.Button.Button--small', { style: 'margin-right:5px;', onclick: e => {
                                        const btn = e.target; btn.disabled = true; btn.innerText = '⏳';
                                        m.request({ method: 'GET', url: app.forum.attribute('apiUrl') + '/seo/inspect', params: { url: item.url }, headers: { 'X-CSRF-Token': app.session.csrfToken } })
                                         .then(res => { this.saveCache(item.url, { checked: true, indexed: res.indexed }); btn.disabled = false; m.redraw(); })
                                         .catch(() => { btn.disabled = false; btn.innerText = 'Hata'; });
                                    }}, cached.checked ? (cached.indexed ? '✅ GSC\'de Var' : '❌ GSC\'de Yok') : '🔍 Kontrol Et'),
                                    m('button.Button.Button--small', { onclick: () => { copyToClipboard(item.url); app.alerts.show({ type: 'success', content: 'Kopyalandı!' }); } }, 'URL Kopyala')
                                ])
                            ]);
                        }))
                    ]),
                    m('div', { style: 'margin-top:20px; text-align:center; display:flex; align-items:center; justify-content:center; gap:12px;' }, [
                        m('button.Button', { disabled: this.data.indexing.page <= 1, onclick: () => { this.data.indexing.page--; this.loadIndexing(); } }, '« Geri'),
                        m('span', { style: 'font-weight:bold; color:#2a5298;' }, 'Sayfa ' + this.data.indexing.page + ' / ' + this.data.indexing.total_pages),
                        m('button.Button', { disabled: this.data.indexing.page >= this.data.indexing.total_pages, onclick: () => { this.data.indexing.page++; this.loadIndexing(); } }, 'İleri »')
                    ])
                ]),

                // ── 3. GÖRSEL SEO ─────────────────────────────────────
                this.activeTab !== 'images' ? null : m('div', [
                    // Üst bar
                    m('div', { style: 'display:flex; align-items:center; justify-content:space-between; padding:16px 22px; background:linear-gradient(135deg,#1e3c72,#2a5298); border-radius:10px; margin-bottom:20px;' }, [
                        m('div', [
                            m('div', { style: 'color:#fff; font-size:22px; font-weight:bold;' }, '📸 ' + this.data.images.count + ' Görsel'),
                            m('div', { style: 'color:rgba(255,255,255,0.75); font-size:13px; margin-top:3px;' }, '[spotter-image] etiketli, Google\'a bildirilebilir içerikler')
                        ]),
                        m('div', { style: 'background:rgba(255,255,255,0.15); border-radius:20px; padding:8px 16px; color:#fff; font-size:12px;' }, [
                            m('i.fas.fa-check-circle', { style: 'color:#a8ff78; margin-right:6px;' }), 'JSON-LD Şema Aktif'
                        ])
                    ]),

                    // Yükleniyor
                    this.loading ? m('div', { style: 'text-align:center; padding:60px;' }, [
                        m('i.fas.fa-spinner.fa-spin', { style: 'font-size:32px; color:#2a5298; display:block; margin-bottom:15px;' }),
                        m('p', { style: 'color:#666;' }, 'Veritabanı taranıyor...')
                    ]) :

                    // Resim grid
                    imgAll.length > 0 ? m('div', [
                        m('div', { style: 'display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px;' },
                            imgSlice.map(img => {
                                const jsonLd = {
                                    '@context': 'https://schema.org', '@type': 'ImageObject',
                                    contentUrl: img.url, name: img.alt, description: img.alt,
                                    url: img.discussion_url || 'https://forum.spottersturkey.com',
                                    thumbnail: img.url,
                                    creator: { '@type': 'Organization', name: 'Spotters Turkey', url: 'https://forum.spottersturkey.com' },
                                    copyrightHolder: { '@type': 'Organization', name: 'Spotters Turkey' },
                                    license: 'https://forum.spottersturkey.com/d/2-fotograf-yukleme-ve-mesaj-paylasma-rehberi',
                                    acquireLicensePage: 'https://forum.spottersturkey.com'
                                };
                                if (img._showJson === undefined) img._showJson = false;
                                return m('div', { style: 'background:#fff; border:1px solid #e0e4e8; border-radius:10px; overflow:hidden; box-shadow:0 1px 4px rgba(0,0,0,0.06); display:flex; flex-direction:column;' }, [
                                    // Görsel — açık gri arka plan, tam göster
                                    m('div', { style: 'background:#f4f5f7; height:160px; display:flex; align-items:center; justify-content:center; overflow:hidden; position:relative;' }, [
                                        m('img', {
                                            src: img.url,
                                            style: 'max-width:100%; max-height:160px; object-fit:contain; display:block;',
                                            onerror: e => { e.target.parentNode.style.background = '#e9ecef'; e.target.style.display = 'none'; }
                                        }),
                                        m('span', { style: 'position:absolute; top:6px; right:6px; background:rgba(42,82,152,0.85); color:#fff; font-size:9px; font-weight:bold; border-radius:4px; padding:2px 6px;' }, '#' + img.image_id)
                                    ]),
                                    // Bilgi
                                    m('div', { style: 'padding:9px 12px; flex:1;' }, [
                                        m('div', { style: 'font-size:11px; font-weight:600; color:#2d3436; margin-bottom:3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; line-height:1.4;' }, img.alt),
                                        m('div', { style: 'font-size:10px; color:#636e72; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;' }, [
                                            m('i.fas.fa-comments', { style: 'margin-right:3px; color:#74b9ff;' }), img.discussion_title
                                        ]),
                                        m('div', { style: 'margin-top:6px; display:flex; gap:10px;' }, [
                                            m('a', { href: img.url, target: '_blank', style: 'font-size:10px; color:#0984e3; text-decoration:none;' }, [m('i.fas.fa-external-link-alt', { style: 'margin-right:2px;' }), 'Aç']),
                                            m('a', { href: img.discussion_url, target: '_blank', style: 'font-size:10px; color:#6c5ce7; text-decoration:none;' }, [m('i.fas.fa-link', { style: 'margin-right:2px;' }), 'Konu'])
                                        ])
                                    ]),
                                    // JSON-LD toggle
                                    m('div', { style: 'border-top:1px solid #f0f2f5; padding:6px 12px; background:#fafbfc;' }, [
                                        m('button', { style: 'background:none; border:none; cursor:pointer; font-size:10px; padding:0; display:flex; align-items:center; gap:5px; width:100%; color:#636e72;', onclick: () => { img._showJson = !img._showJson; m.redraw(); } }, [
                                            m('i.fas', { className: img._showJson ? 'fa-code' : 'fa-code', style: 'color:#a8ff78; background:#2d3436; border-radius:3px; padding:2px 4px; font-size:8px;' }),
                                            m('span', { style: 'font-weight:600; color:#2d3436;' }, 'JSON-LD'),
                                            m('span', { style: 'margin-left:auto; color:#b2bec3; font-size:9px;' }, img._showJson ? 'Gizle' : 'Göster')
                                        ]),
                                        img._showJson ? m('pre', { style: 'font-size:8.5px; color:#d4d4d4; background:#1e1e1e; margin:6px -12px -6px; padding:8px 12px; overflow-x:auto; white-space:pre-wrap; word-break:break-all; max-height:160px; overflow-y:auto;' },
                                            JSON.stringify(jsonLd, null, 2)
                                        ) : null
                                    ])
                                ]);
                            })
                        ),
                        // Sayfalama
                        imgTotalPg > 1 ? m('div', { style: 'margin-top:25px; text-align:center; display:flex; align-items:center; justify-content:center; gap:12px;' }, [
                            m('button.Button', { disabled: imgPg <= 1, onclick: () => { this.data.images.page--; m.redraw(); } }, '« Geri'),
                            m('span', { style: 'font-weight:bold; color:#2a5298;' }, 'Sayfa ' + imgPg + ' / ' + imgTotalPg + '  (' + imgAll.length + ' görsel)'),
                            m('button.Button', { disabled: imgPg >= imgTotalPg, onclick: () => { this.data.images.page++; m.redraw(); } }, 'İleri »')
                        ]) : null
                    ]) :
                    m('div', { style: 'text-align:center; padding:60px; color:#999;' }, [
                        m('i.fas.fa-images', { style: 'font-size:48px; display:block; margin-bottom:15px; color:#ddd;' }),
                        m('p', { style: 'font-size:16px; margin:0; color:#555;' }, 'Kayıtlı görsel bulunamadı.')
                    ])
                ]),

                // ── 4. AYARLAR ────────────────────────────────────────
                this.activeTab !== 'settings' ? null : m('div.SeoCard', [
                    m('h3', { style: 'margin-top:0;' }, 'Google Servisleri ve Temel Ayarlar'),
                    m('div.Form-group', [m('label', 'Google Analytics 4 Ölçüm Kimliği (G-XXXXXXXX)'), m('input.FormControl',    { bidi: this.setting('spottersturkey-seo.ga_id') })]),
                    m('div.Form-group', [m('label', 'GA4 Mülk Kimliği (Sayısal ID)'),                   m('input.FormControl',    { bidi: this.setting('spottersturkey-seo.ga_id_number') })]),
                    m('div.Form-group', [m('label', 'Google Search Console Doğrulama Kodu'),             m('input.FormControl',    { bidi: this.setting('spottersturkey-seo.gsc_code') })]),
                    m('div.Form-group', [m('label', 'Google Ads Yayıncı Kimliği (ca-pub-XXXXXXXX)'),    m('input.FormControl',    { bidi: this.setting('spottersturkey-seo.ads_client') })]),
                    m('div.Form-group', [m('label', 'Site Açıklaması (Meta Description)'),              m('textarea.FormControl', { bidi: this.setting('spottersturkey-seo.meta_description_prefix') })]),
                    m('div.Form-group', [m('label', 'Meta Anahtar Kelimeler'),                          m('textarea.FormControl', { bidi: this.setting('spottersturkey-seo.meta_keywords') })]),
                    m('div.Form-group', [m('label', 'Cron-Job.org Gizli Anahtarı'),                     m('input.FormControl',    { bidi: this.setting('spottersturkey-seo.trigger_secret') })])
                ])
            ])
        ]);
    }
}

app.initializers.add('spottersturkey-seo-pack', () => {
    app.extensionData.for('spottersturkey-seo-pack').registerSetting(function () {
        return m(SeoAdminPage, { setting: this.setting.bind(this) });
    });
});
